Problem:
A furniture store only stocks and sells dining tables and chairs. The profit per dining table is $350 and the profit per chair is $75. There is 500 sq ft of space available and a dining table requires 8 sq ft of floor space while a chair requires 2 sq ft. Because chairs sell in larger quantities, at least 70% of all furniture in the store must be chairs. In terms of capital, a dining table ties up $1000 in capital and a chair ties up $150 in capital. The company wants a maximum of $20000 worth of capital tied up at any time. Formulate an LP to maximize profit.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "dining tables",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "chairs",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "dining tables",
     "coef": 350.0
    },
    {
     "var": "chairs",
     "coef": 75.0
    }
   ]
  },
  "constraints": [
   {
    "name": "floor space",
    "terms": [
     {
      "var": "dining tables",
      "coef": 8.0
     },
     {
      "var": "chairs",
      "coef": 2.0
     }
    ],
    "sense": "<=",
    "rhs": 500.0
   },
   {
    "name": "chair share of furniture",
    "terms": [
     {
      "var": "dining tables",
      "coef": -0.7
     },
     {
      "var": "chairs",
      "coef": 0.3
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "capital",
    "terms": [
     {
      "var": "dining tables",
      "coef": 1000.0
     },
     {
      "var": "chairs",
      "coef": 150.0
     }
    ],
    "sense": "<=",
    "rhs": 20000.0
   }
  ]
 },
 "facts": {
  "objective": 9975.0,
  "values": {
   "dining tables": 0.0,
   "chairs": 133.0
  },
  "binding": [],
  "slack": {
   "floor space": 234.0,
   "chair share of furniture": 39.9,
   "capital": 50.0
  },
  "shadow_prices": null,
  "limits": {
   "floor space": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "chair share of furniture": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "capital": {
    "dropped_improves": true,
    "loosened_improves": false
   }
  }
 }
}
